begin;

-- activities (13 แถว)
insert into activities (id, title_th, date, location, description, featured, cover_id, status)
select (r->>'id')::uuid as id,
       nullif(r->>'title_th','') as title_th,
       nullif(r->>'date','')::date as date,
       nullif(r->>'location','') as location,
       nullif(r->>'description','') as description,
       coalesce(lower(r->>'featured') in ('yes','true','1'), false) as featured,
       nullif(r->>'cover_id','') as cover_id,
       coalesce(nullif(r->>'status',''),'draft')::content_status as status
from jsonb_array_elements($j$[{"id":"4c314d14-4169-5141-bc0e-f4a03230a4d4","title_th":"Sport Day x สานสัมพันธ์","date":"2025-02-15","location":null,"description":null,"featured":"no","cover_id":"1BQqbY-Yg03tyWfLX5iEuolXhUD-f1x_N","status":"published"},{"id":"e854e4ea-4f0a-5b99-ade6-7cdb641b6601","title_th":"Halaqah x Tawhid","date":"2025-09-13","location":null,"description":null,"featured":"no","cover_id":"1B_HJ1_H8t4-xTHb4-VMluYmiYsro_7WP","status":"published"},{"id":"5f45e589-7361-51a9-9fbc-b928ad63d5ef","title_th":"Final Advice to the Strangers","date":"2026-07-26","location":"ห้องประชุม Co-working Space ชั้น 1 อาคารกีฬาและสุขภาพ มหาวิทยาลัยเชียงใหม่","description":"ขอเชิญทุกท่านร่วมรับฟังบรรยายศาสนาในหัวข้อ\n\nFinal Advice to the Strangers\nคำสั่งเสียแด่บรรดาผู้แปลกหน้า\n🕟 เวลา 16.30–18.30 น.","featured":"no","cover_id":"1DP2Le9XWXk9_6RTNaodQUHZ4VC0rD--U","status":"published"},{"id":"1c910b58-6c35-5d7d-aa5a-27dd6c04f4e5","title_th":"ค่ายหนาวสายใยล้อมรัก","date":"2025-06-28","location":"ศูนย์อิสลามศึกษาแม่ป๋าม","description":"ค่ายหนาวแสนสนุกที่เราจะได้ใช้เวลาร่วมกันสร้างสรรคกิจกรรมให้กับสังคม","featured":"no","cover_id":"1OPeE26Z4LSjCHebe6tTY-Nr4J2Fk_iY7","status":"published"},{"id":"b1535b22-a73c-5660-950e-fbd182d3bd68","title_th":"Steadfastness x จุดยืน","date":"2025-07-27","location":"ค่ายสวนสน","description":"ค่ายพักแรม 2 คืน กิจกรรมศาสนาและการสร้างทีม","featured":"no","cover_id":"1QuGsILqbcMDxWKYGcNtwS6Zz0dDFdH6_","status":"published"},{"id":"2b0eb7ed-ef2f-5b3b-a11b-53e46ba2f219","title_th":"โครงการแจกข้าวน้องปี1","date":"2026-07-03","location":"ศูนย์อาหารหลักมหาลัยเชียงใหม่","description":"ꕁ เนื่องด้วยทางชมรมนักศึกษามุสลิม จะจัดโครงการ “แจกข้าวน้องมุสลิมปี1(Meals for Smiles)” เพื่อส่งต่อความอบอุ่นและแบ่งเบาภาระค่าใช้จ่ายให้กับน้อง ๆ นักศึกษาชั้นปีที่ 1 โดยมอบอาหารมื้อเย็นเป็นระยะเวลา 10 วัน\nระหว่างวันที่ 22 มิถุนายน - 3 กรกฎาคม 2569\n(เฉพาะวันจันทร์ – วันศุกร์)","featured":"no","cover_id":"1S0P-chmWtAgFG3JJeAMLo1ZJJIEMxKu_","status":"published"},{"id":"45a7d5a1-ba9c-5f0a-955d-778e50d0dbfa","title_th":"ประตูสู่การมั่นคงในศาสนาและการสำเร็จทั้งในโลกนี้และโลกหน้า","date":"2025-11-30","location":null,"description":null,"featured":"no","cover_id":"1SBXiNQeMdhHl97DWlrSM-J0fYrT-fkHj","status":"published"},{"id":"bfa783bc-4248-5385-8afb-51715c594b52","title_th":"โครงการแจกข้าวน้องปี1","date":"2025-06-16","location":null,"description":null,"featured":"","cover_id":"1U54M3vVb4L4YBvozQSqYQ4-Q8GH3i1Mw","status":"published"},{"id":"62394163-12c3-5d34-aac5-8aa545fae582","title_th":"บรรยายศาสนา อากีดะฮฺกับหัวใจ","date":"2024-11-30","location":null,"description":null,"featured":"no","cover_id":"1XvvUAwOirUxCmxXrQBeBzGU-K2UOg9y_","status":"published"},{"id":"f84b117a-fa08-5953-8395-0a4df0b29ef3","title_th":"Steadfastness x จุดยืน","date":"2024-09-14","location":null,"description":null,"featured":"no","cover_id":"1dn49GhLGTKq8_4G1EJSb9ij3WT_okP28","status":"published"},{"id":"151590c6-8ce5-56c4-a5fa-8f009f4563f2","title_th":"โครงการรับน้องปีการศึกษา 2568","date":"2025-07-15","location":null,"description":null,"featured":"no","cover_id":"1iIac4Z-EYT8OO--YuM4GJtIMTBthoIIy","status":"published"},{"id":"3cf05ef7-b8b0-5b0d-aff6-25bedb057bd8","title_th":"กิจกรรมปฐมนิเทศนักศึกษามุสลิม ☝🏻","date":"2026-08-01","location":"ศูนย์วิจัย บูรณาการฯ สาธิตและฝึกอบรมนวัตกรรมการเกษตร(มช.วิทยาเขตแม่เหียะ)","description":"✨ โครงการปฐมนิเทศ ประจำปี 2569\nFaith & Friendship ☝🏻🤍\nขอเชิญชวนน้อง ๆ มาร่วมทำความรู้จักเพื่อนใหม่ รุ่นพี่ และสังคมมุสลิม พร้อมร่วมกิจกรรมที่พี่ ๆ ตั้งใจเตรียมไว้ เพื่อให้น้อง ๆ ได้เริ่มต้นชีวิตในรั้วมหาวิทยาลัยอย่างอบอุ่น เต็มไปด้วยมิตรภาพ และความทรงจำที่ดี","featured":"no","cover_id":"1uKsMsokA9ukBhHsPsoD20Upi1_MJR15u","status":"published"},{"id":"9d7b462c-d1bd-5b95-9c31-90b2cd576d14","title_th":"MCCMU x FirstMeetFirstStep","date":"2026-06-21","location":"หน้าอาคารพละศึกษา","description":"ขอเชิญชวนทุกคนแวะเติมพลังที่บูธ Halal Food Booth✨\nพร้อมร่วมสนุกกับกิจกรรมตอบคำถามและให้ความรู้ศาสนาภายในบูธ 💜\n🕟 16:30 – 20:00 น.","featured":"no","cover_id":"1yjKvWzdH7ioTrXYkbbnJ3g0P22RYOZ2R","status":"published"}]$j$::jsonb) as r
on conflict (id) do update set title_th=excluded.title_th, date=excluded.date, location=excluded.location, description=excluded.description, featured=excluded.featured, cover_id=excluded.cover_id, status=excluded.status;

