-- albums (5 แถว)
insert into albums (id, title, date, description, folder_id, cover_id, status)
select (r->>'id')::uuid as id,
       nullif(r->>'title','') as title,
       nullif(r->>'date','')::date as date,
       nullif(r->>'description','') as description,
       nullif(r->>'folder_id','') as folder_id,
       nullif(r->>'cover_id','') as cover_id,
       coalesce(nullif(r->>'status',''),'draft')::content_status as status
from jsonb_array_elements($j$[{"id":"64f52e3d-88c2-5935-a253-28749dbd9621","title":"Sport Day","date":"2025-02-05","description":"กิจกรรมกีฬาสีของชมรมนักศึกษามุสลิม เป็นกิจกรรมที่เปิดโอกาสให้ได้ใช้เวลาร่วมกันผ่านการแข่งขันกีฬาและกิจกรรมสร้างสรรค์ในบรรยากาศที่สนุกสนานและเป็นกันเอง โดยมุ่งเน้นการสร้างความสามัคคี ความสัมพันธ์อันดี และการทำงานร่วมกันระหว่างนักศึกษาต่างคณะและต่างชั้นปี นอกจากการส่งเสริมสุขภาพและการออกกำลังกายแล้ว กิจกรรมยังเป็นพื้นที่ให้สมาชิกชมรมได้เรียนรู้การเป็นผู้นำ การทำงานเป็นทีม การมีน้ำใจนักกีฬา และการเคารพซึ่งกันและกัน พร้อมทั้งสร้างความภาคภูมิใจในความเป็นส่วนหนึ่งของชมรมนักศึกษามุสลิม กิจกรรมนี้จึงเป็นมากกว่าการแข่งขันกีฬา แต่เป็นอีกหนึ่งกิจกรรมที่ช่วยเติมเต็มประสบการณ์ชีวิตในมหาวิทยาลัย สร้างมิตรภาพที่ดีระหว่างมหาวิทยาลัยด้วยกัน","folder_id":"1thJ6txAT09RAwx8qtP7cFivVGyjEdiNQ","cover_id":"1BQqbY-Yg03tyWfLX5iEuolXhUD-f1x_N","status":"published"},{"id":"ef84f29d-0f03-55f3-b9bb-d8b1823011c8","title":"ค่ายหนาวสายใยล้อมรัก","date":"2026-03-20","description":"กิจกรรมค่ายหนาวไปสร้างรอยยิ้มและแบ่งปันความสุขกับน้อง ๆ ในพื้นที่ ต.แม่ป๋าม อ.เชียงดาว จ.เชียงใหม่ ผ่านกิจกรรมสร้างสรรค์ที่ทั้งสนุกและะมีความหมาย\nภายในกิจกรรมให้สมาชิกในชมรมได้ร่วมกันวางแผนและจัดกิจกรรมเพื่อส่งเสริมการเรียนรู้และพัฒนาทักษะของน้อง ๆ พร้อมทั้งเรียนรู้การทำงานเป็นทีม การเสียสละ และการใช้เวลาร่วมกันท่ามกลางบรรยากาศอันอบอุ่น ท่ามกลางหุบเขา พร้อมอากาศเย็นสบายตลอดกิจกรรม สร้างความทรงจำดี ๆ ที่จะได้รับกลับมา ค่ายแห่งนี้ยังเป็นพื้นที่แห่งการเรียนรู้ การแบ่งปัน และการเติบโตไปพร้อมกัน ทั้งในฐานะผู้ให้และผู้รับ เพราะทุกกิจกรรมเล็ก ๆ ที่เราร่วมกันสร้าง อาจกลายเป็นความสุขและแรงบันดาลใจที่ยิ่งใหญ่สำหรับใครหลายคน","folder_id":"1RKtDbZYFDBMSeB9NkeOOfSHSYAKe8-Ko","cover_id":"1OPeE26Z4LSjCHebe6tTY-Nr4J2Fk_iY7","status":"published"},{"id":"dd1f1d5c-738d-5759-b16d-452f0225278c","title":"Steadfastness","date":"2026-09-27","description":"กิจกรรมที่มีส่วนร่วมอย่างทั่วถึง โดยมีการแลกเปลี่ยนประสบการณ์ การสะท้อนมุมมอง และการทำกิจกรรมร่วมกัน ระหว่างนักศึกษามุสลิมจากมหาวิทยาลัยต่าง ๆ ในพื้นที่ภาคเหนือ อาทิ มหาวิทยาลัยแม่ฟ้าหลวง มหาวิทยาลัยราชภัฏเชียงใหม่ มหาวิทยาลัยแม่โจ้ มหาวิทยาลัยพายัพ มหาวิทยาวิทยาลัยธรรมศาสตร์ วิทยาเขตลำปาง มหาวิทยาลัยพะเยา มหาวิทยาลัยนเรศวร เพื่อให้ผู้เข้าร่วมได้เรียนรู้ รับฟัง ผ่านการตั้งคำถามต่อกันอย่างสร้างสรรค์ ทั้งนี้ ไม่ได้จำกัดผู้เข้าร่วมเพียงนักศึกษามุสลิมเท่านั้น แต่ยังเปิดโอกาสสำหรับต่างศาสนิกเข้าร่วมด้วย","folder_id":"1kxyhcWHzb1GP36AkuWHQTF6EgUAT095H","cover_id":"1QuGsILqbcMDxWKYGcNtwS6Zz0dDFdH6_","status":"published"},{"id":"85670033-6afc-5e1e-b2d0-167dd9fbba89","title":"โครงการแจกข้าวน้องปี1","date":"2026-07-03","description":null,"folder_id":"1011NpDvg_QXh_OC4ATOpA1VHbo-WENSa","cover_id":"1S0P-chmWtAgFG3JJeAMLo1ZJJIEMxKu_","status":"published"},{"id":"3e82db77-3a5f-5900-b26b-eb8d28ce4a95","title":"โครงการรับน้องปีการศึกษา 2568","date":"2026-07-19","description":"กิจกรรมที่จัดขึ้นเพื่อให้นักศึกษาใหม่ได้ทำความรู้จักกับเพื่อน ๆ รุ่นเดียวกัน รุ่นพี่ และบุคลากรของมหาวิทยาลัย ผ่านกิจกรรมสนุก ๆ ที่ช่วยสร้างความคุ้นเคย เรียนรู้การใช้ชีวิตในรั้วมหาวิทยาลัย และแลกเปลี่ยนประสบการณ์ที่จะเป็นประโยชน์ในช่วงเริ่มต้น นอกจากจะได้เพื่อนใหม่และสร้างความสัมพันธ์ที่ดีแล้ว ยังเป็นพื้นที่ให้ทุกคนได้เรียนรู้การอยู่ร่วมกันในสังคมที่มีความหลากหลาย เปิดใจรับฟังกันและกัน พร้อมทั้งได้ทบทวนและแลกเปลี่ยนมุมมองผ่านกิจกรรมต่าง ๆ เราอยากให้น้อง ๆ ทุกคนได้เริ่มต้นชีวิตมหาวิทยาลัยอย่างมั่นใจ มีเครือข่ายเพื่อนจากหลากหลายคณะและต่างชั้นปี สามารถปรับตัวกับการเรียนและการใช้ชีวิตได้อย่างมีความสุข พร้อมทั้งยังคงรักษาอัตลักษณ์และปฏิบัติตามหลักศาสนาอิสลามได้อย่างเหมาะสม","folder_id":"1wT_DCf-JMv-WARh7o19KVyjWR5c2UAlY","cover_id":"1iIac4Z-EYT8OO--YuM4GJtIMTBthoIIy","status":"published"}]$j$::jsonb) as r
on conflict (id) do update set title=excluded.title, date=excluded.date, description=excluded.description, folder_id=excluded.folder_id, cover_id=excluded.cover_id, status=excluded.status;

